                if (!token) {
                    window.location.href = '/login';
                    return;
                }

                const response = await fetch('/api/reports/banks', {
                    headers: { 'Authorization': 'Bearer ' + token }
                });

                if (!response.ok) {
                    throw new Error('Failed to load banks report');
                }

                const data = await response.json();
