    function renderSidebarCount(link, count) {
      if (!link) return;
      var badge = link.querySelector('.gps-count-badge');

      if (count == null) {
        if (badge) badge.remove();
        return;
      }

      var n = typeof count === 'number' ? count : 0;

      if (!link.dataset.gpsPrevDisplay) {
        link.dataset.gpsPrevDisplay = link.style.display || '';
      }

      if (n <= 0) {
        link.setAttribute('data-gps-hidden-by-count', '1');
        link.style.display = 'none';
        if (badge) badge.remove();
        return;
      }

      link.removeAttribute('data-gps-hidden-by-count');
      link.style.display = link.dataset.gpsPrevDisplay;

      if (!badge) {
        badge = document.createElement('span');
        badge.className = 'gps-count-badge';
        link.appendChild(badge);
      }
      badge.textContent = String(n);
    }

    function hydrateSidebarFilterCounts() {
      fetch('/api/sidebar-filter-counts', { credentials: 'same-origin' })
        .then(function (res) { return res.ok ? res.json() : Promise.reject(new Error('Failed to load sidebar counts')); })
        .then(function (payload) {
          if (!payload || payload.success !== true) return;

          var customers = payload.customers || {};
          var requests = payload.requests || {};
          var requestStatusCounts = requests.byState || {};

          document.querySelectorAll('#global-persistent-sidebar [data-customer-rating-filter]').forEach(function (link) {
            var key = link.getAttribute('data-customer-rating-filter') || 'all';
            var value = customers[key];
            // If a key is absent from the payload, it effectively means 0 for this scope.
            if (typeof value !== 'number') value = 0;
            renderSidebarCount(link, value);
          });

          document.querySelectorAll('#global-persistent-sidebar [data-request-status-filter]').forEach(function (link) {
            var key = link.getAttribute('data-request-status-filter') || 'all';
            var value = key === 'all' ? requests.all : requestStatusCounts[key];
            // Missing key => 0 requests for that status in this scope.
            if (typeof value !== 'number') value = 0;
            renderSidebarCount(link, value);
          });

          // المكتملة link — always visible, just show the count badge
          var completedLink = document.querySelector('#global-persistent-sidebar [data-completed-requests-link]');
          if (completedLink) {
            var completedN = typeof requests.completed === 'number' ? requests.completed : 0;
            var existingBadge = completedLink.querySelector('.gps-count-badge');
            if (completedN > 0) {
              if (!existingBadge) {
                var newBadge = document.createElement('span');
                newBadge.className = 'gps-count-badge';
                completedLink.appendChild(newBadge);
                existingBadge = newBadge;
              }
              existingBadge.textContent = String(completedN);
            } else if (existingBadge) {
              existingBadge.remove();
            }
          }

          var completedCustomersLink = document.querySelector('#global-persistent-sidebar [data-completed-customers-link]');
          if (completedCustomersLink) {
            var completedCustomersN = typeof customers.completed === 'number' ? customers.completed : 0;
            var existingCustomersBadge = completedCustomersLink.querySelector('.gps-count-badge');
            if (completedCustomersN > 0) {
              if (!existingCustomersBadge) {
                var newCustomersBadge = document.createElement('span');
                newCustomersBadge.className = 'gps-count-badge';
                completedCustomersLink.appendChild(newCustomersBadge);
                existingCustomersBadge = newCustomersBadge;
              }
              existingCustomersBadge.textContent = String(completedCustomersN);
            } else if (existingCustomersBadge) {
              existingCustomersBadge.remove();
            }
          }

          var archivedCustomersLink = document.querySelector('#global-persistent-sidebar [data-archived-customers-link]');
          if (archivedCustomersLink) {
            var archivedCustomersN = typeof customers.archived === 'number' ? customers.archived : 0;
            var existingArchivedBadge = archivedCustomersLink.querySelector('.gps-count-badge');
            if (archivedCustomersN > 0) {
              if (!existingArchivedBadge) {
                var newArchivedBadge = document.createElement('span');
                newArchivedBadge.className = 'gps-count-badge';
                archivedCustomersLink.appendChild(newArchivedBadge);
                existingArchivedBadge = newArchivedBadge;
              }
              existingArchivedBadge.textContent = String(archivedCustomersN);
            } else if (existingArchivedBadge) {
              existingArchivedBadge.remove();
            }
          }
        })
        .catch(function () {});
    }

    function backToAdminList(event, listPath) {
      try {
        if (event) event.preventDefault();
        var ref = document.referrer ? new URL(document.referrer) : null;
        if (ref && ref.origin === window.location.origin && ref.pathname === listPath) {
          window.history.back();
          return false;
        }
      } catch (e) {}
      window.location.href = listPath;
      return false;
    }
    window.backToAdminList = backToAdminList;

    function applySidebarFilterLink(link) {
      if (!link) return false;
      var href = link.getAttribute('href');
      if (!href) return false;

      var url = new URL(href, window.location.origin);
      if (url.pathname !== window.location.pathname) return false;

      var handled = false;
      var params = new URLSearchParams(window.location.search);

      if (url.pathname === '/admin/customers' && (url.searchParams.has('ratingFilter') || url.searchParams.has('requestsFilter'))) {
        var rating = url.searchParams.get('ratingFilter') || 'all';
        var requests = url.searchParams.get('requestsFilter');
        if (requests === null || requests === '') {
          requests = (ROLE_ID === 4 || ROLE_ID === 6) ? '0' : 'all';
        }
        var customerSearchEl = document.getElementById('searchInput');
        var customerFieldEl = document.getElementById('filterField');
        var customerDateEl = document.getElementById('dateRangeFilter');
        var ratingEl = document.getElementById('ratingFilter');
        var requestsEl = document.getElementById('requestsFilter');
        if (customerSearchEl) customerSearchEl.value = '';
        if (customerFieldEl) customerFieldEl.value = 'all';
        if (customerDateEl) customerDateEl.value = 'all';
        if (ratingEl) ratingEl.value = rating;
        if (requestsEl) requestsEl.value = requests;
        params.delete('search');
        params.delete('filterField');
        params.delete('dateRangeFilter');
        params.set('ratingFilter', rating);
        params.set('requestsFilter', requests);
        handled = true;
      }

      if (url.pathname === '/admin/requests' && url.searchParams.has('requestStatusFilter')) {
        var status = url.searchParams.get('requestStatusFilter') || 'all';
        var requestSearchEl = document.getElementById('searchInput');
        var requestFieldEl = document.getElementById('filterField');
        var statusEl = document.getElementById('statusFilter');
        if (requestSearchEl) requestSearchEl.value = '';
        if (requestFieldEl) requestFieldEl.value = 'all';
        if (statusEl) statusEl.value = status;
        params.delete('search');
        params.delete('filterField');
        if (status && status !== 'all') {
          params.set('statusFilter', status);
          params.set('requestStatusFilter', status);
        } else {
          params.delete('statusFilter');
          params.delete('requestStatusFilter');
        }
        handled = true;
      }

      if (url.pathname === '/admin/follow-ups' && (url.searchParams.has('followupLinkFilter') || url.searchParams.has('followupPriorityFilter'))) {
        var followupLink = url.searchParams.get('followupLinkFilter') || 'all';
        var followupPriority = url.searchParams.get('followupPriorityFilter') || 'all';
        var followupLinkEl = document.getElementById('followupLinkFilterSelect');
        var followupPriorityEl = document.getElementById('followupPriorityFilterSelect');
        if (followupLinkEl) followupLinkEl.value = followupLink;
        if (followupPriorityEl) followupPriorityEl.value = followupPriority;
        params.set('followupLinkFilter', followupLink);
        params.set('followupPriorityFilter', followupPriority);
        handled = true;
      }

      if (!handled) return false;

      var qs = params.toString();
      window.history.pushState({}, '', window.location.pathname + (qs ? '?' + qs : ''));
      applyGlobalSidebarPermissions();

      if (url.pathname === '/admin/follow-ups' && typeof window.loadFollowUps === 'function') {
        window.loadFollowUps();
      } else if (typeof window.filterTable === 'function') {
        window.filterTable();
      }
      return true;
    }

    document.addEventListener('click', function (event) {
      var filterLink = event.target.closest('#global-persistent-sidebar a[href]');
      if (filterLink && applySidebarFilterLink(filterLink)) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }

      var toggle = event.target.closest('#global-persistent-sidebar [data-customers-collapsible] [data-customers-toggle]');
      if (!toggle) {
        toggle = event.target.closest('#global-persistent-sidebar [data-requests-collapsible] [data-requests-toggle]');
      }
      if (!toggle) {
        toggle = event.target.closest('#global-persistent-sidebar [data-followups-collapsible] [data-followups-toggle]');
      }
      if (!toggle) return;
      var wrapper =
        toggle.closest('[data-customers-collapsible]') ||
        toggle.closest('[data-requests-collapsible]') ||
        toggle.closest('[data-followups-collapsible]');
      if (!wrapper) return;
      event.preventDefault();
      event.stopPropagation();
      wrapper.classList.toggle('gps-open');
    });

    applyGlobalSidebarPermissions();
    hydrateSidebarFilterCounts();
    document.addEventListener('DOMContentLoaded', applyGlobalSidebarPermissions);
    document.addEventListener('DOMContentLoaded', hydrateSidebarFilterCounts);
