              var bsPre = document.getElementById('newRequestSelectedBank');
              if (bsPre && bsPre.value) {
                var bPre = parseInt(bsPre.value, 10);
                if (!isNaN(bPre) && bPre > 0) loadBankAgentsForBank(bPre);
              }
